# ==========================================================================
# 基本構成
#   底グラフ X: 頂点 0..m-1、辺は (u, v, (a,b)) の list。
#   u == v はループ、(a,b) ∈ Z^2 が voltage。
# ==========================================================================

def volt_laplacian(m, edges):
    """2 変数 voltage ラプラシアン L(z,w) ∈ Mat_m(Z[z^±,w^±])。"""
    L = matrix(RL, m, m)
    for (u, v, ab) in edges:
        a, b = ab
        mon = zL**a * wL**b
        if u == v:
            L[u, u] += _sage_const_2  - mon - mon**(-_sage_const_1 )
        else:
            L[u, u] += _sage_const_1 
            L[v, v] += _sage_const_1 
            L[u, v] -= mon
            L[v, u] -= mon**(-_sage_const_1 )
    return L


def derived_edges(m, edges, N, Np):
    """導来グラフ X_{N,N'} の辺 list。頂点番号は (i,j,u) -> (i*Np + j)*m + u。"""
    out = []
    for (u, v, ab) in edges:
        a, b = ab
        for i in range(N):
            for j in range(Np):
                x = (i * Np + j) * m + u
                y = (((i + a) % N) * Np + ((j + b) % Np)) * m + v
                out.append((x, y))
    return out


def int_laplacian(nv, uedges):
    """多重グラフ（ループ可）のラプラシアン。ループは寄与しない。"""
    Lap = matrix(ZZ, nv, nv)
    for (x, y) in uedges:
        if x == y:
            continue
        Lap[x, x] += _sage_const_1 
        Lap[y, y] += _sage_const_1 
        Lap[x, y] -= _sage_const_1 
        Lap[y, x] -= _sage_const_1 
    return Lap


def kappa_from_laplacian(Lap):
    """Kirchhoff: 1 行 1 列を除いた小行列式（頂点 1 個なら 1）。"""
    n = Lap.nrows()
    if n == _sage_const_1 :
        return ZZ(_sage_const_1 )
    return Lap[_sage_const_1 :, _sage_const_1 :].determinant()


def kappa_derived(m, edges, N, Np):
    nv = m * N * Np
    return kappa_from_laplacian(int_laplacian(nv, derived_edges(m, edges, N, Np)))


def n_components(nv, uedges):
    par = list(range(nv))
    def find(x):
        while par[x] != x:
            par[x] = par[par[x]]
            x = par[x]
        return x
    for (x, y) in uedges:
        rx, ry = find(x), find(y)
        if rx != ry:
            par[rx] = ry
    return len(set(find(x) for x in range(nv)))


def cycle_voltage_subgroup(m, edges):
    """全域木を 1 つ取り、非木辺の基本閉路 voltage β_e ∈ Z^2 を並べた行列（行が β_e）。
       X が非連結なら None を返す。"""
    adj = {}
    for idx, (u, v, ab) in enumerate(edges):
        adj.setdefault(u, []).append((v, ab, idx, +_sage_const_1 ))
        adj.setdefault(v, []).append((u, ab, idx, -_sage_const_1 ))
    h = {_sage_const_0 : vector(ZZ, [_sage_const_0 , _sage_const_0 ])}
    tree = set()
    stack = [_sage_const_0 ]
    while stack:
        x = stack.pop()
        for (y, ab, idx, sgn) in adj.get(x, []):
            if y not in h and idx not in tree:
                h[y] = h[x] + sgn * vector(ZZ, list(ab))
                tree.add(idx)
                stack.append(y)
    if len(h) < m:
        return None                      # X が非連結
    rows = []
    for idx, (u, v, ab) in enumerate(edges):
        if idx in tree:
            continue
        rows.append(vector(ZZ, list(ab)) + h[u] - h[v])
    if not rows:
        rows = [vector(ZZ, [_sage_const_0 , _sage_const_0 ])]
    return matrix(ZZ, rows)


def connected_by_criterion(m, edges, N, Np):
    """判定: Λ_X + (NZ × N'Z) = Z^2 か。X が非連結なら False。"""
    B = cycle_voltage_subgroup(m, edges)
    if B is None:
        return False
    rows = [list(r) for r in B.rows()] + [[N, _sage_const_0 ], [_sage_const_0 , Np]]
    M = matrix(ZZ, rows)
    d = M.elementary_divisors()
    d = [x for x in d if x != _sage_const_0 ]
    return len(d) == _sage_const_2  and all(x == _sage_const_1  for x in d)


# ==========================================================================
# det L(z,w) 周り
# ==========================================================================

def detL(m, edges):
    """det L(z,w) ∈ Z[z^±,w^±]。"""
    return volt_laplacian(m, edges).determinant()


def laurent_to_poly(D):
    """Laurent 多項式 D を z^r w^s * F(z,w)（F ∈ Z[z,w], z,w で割り切れない）に分解し F を返す。"""
    if D == _sage_const_0 :
        return RP(_sage_const_0 )
    ed = D.exponents()
    rmin = min(e[_sage_const_0 ] for e in ed)
    smin = min(e[_sage_const_1 ] for e in ed)
    F = RP(_sage_const_0 )
    for e, c in zip(ed, D.coefficients()):
        F += ZZ(c) * zP**(e[_sage_const_0 ] - rmin) * wP**(e[_sage_const_1 ] - smin)
    return F


def content_of(D):
    """content_{z,w}(D) ∈ Z_{>0}（D ≠ 0）。"""
    return gcd([ZZ(c) for c in D.coefficients()])


def shifted_poly(m, edges):
    """p(T,S) := F(1+T, 1+S) ∈ Z[T,S]（F は上の numerator polynomial）。"""
    F = laurent_to_poly(detL(m, edges))
    out = RT(_sage_const_0 )
    for e, c in zip(F.exponents(), F.coefficients()):
        out += ZZ(c) * (_sage_const_1  + TT)**ZZ(e[_sage_const_0 ]) * (_sage_const_1  + SS)**ZZ(e[_sage_const_1 ])
    return out


def monomial_reduction_data(m, edges, ell):
    """f₁ mod ℓ が T^a S^b × 単元 か判定する。
       返り値 (is_monomial, a, b, mu)。det L = 0 なら None。"""
    D = detL(m, edges)
    if D == _sage_const_0 :
        return None
    mu = ZZ(content_of(D)).valuation(ell)
    p = shifted_poly(m, edges)
    Fl = GF(ell)
    RTl = PolynomialRing(Fl, 'T,S')
    pbar = RTl(p / ell**mu)
    exps = pbar.exponents()
    assert len(exps) > _sage_const_0 , "f_1 mod ell must be nonzero"
    a = min(e[_sage_const_0 ] for e in exps)
    b = min(e[_sage_const_1 ] for e in exps)
    ok = all(e[_sage_const_0 ] >= a and e[_sage_const_1 ] >= b for e in exps) and pbar.monomial_coefficient(
        RTl.gen(_sage_const_0 )**a * RTl.gen(_sage_const_1 )**b) != _sage_const_0 
    return (ok, ZZ(a), ZZ(b), mu)


# ==========================================================================
# ∏_{(ζ,ξ)≠(1,1)} det L(ζ,ξ) の厳密計算（終結式のみ、根号・数値なし）
#
#   D = z^r w^s F,  ζ,ξ は 1 の冪根なので z^r w^s の寄与は絶対値 1（v_ℓ = 0）。
#   ∏_{(ζ,ξ)≠(1,1)} F(ζ,ξ)
#     = [∏_{ζ^N=1, ζ≠1} G(ζ)] · [∏_{ξ^{N'}=1, ξ≠1} F(1,ξ)],
#   G(z) := Res_w(w^{N'}-1, F(z,w)) = ∏_{ξ^{N'}=1} F(z,ξ)
#   （w^{N'}-1 はモニックなので Res はそのまま値の積）。
# ==========================================================================

def prod_over_nontrivial(m, edges, N, Np):
    """∏_{(ζ,ξ)≠(1,1)} det L(ζ,ξ) の絶対値（0 なら 0）を返す。"""
    if N == _sage_const_1  and Np == _sage_const_1 :
        return ZZ(_sage_const_1 )                      # 空積
    D = detL(m, edges)
    if D == _sage_const_0 :
        return ZZ(_sage_const_0 )
    F = laurent_to_poly(D)
    Rz = PolynomialRing(ZZ, 'z')
    zz = Rz.gen()
    Rw = PolynomialRing(ZZ, 'w')
    ww = Rw.gen()
    # part1 = ∏_{ζ≠1} ∏_{ξ} F(ζ,ξ)
    if N > _sage_const_1 :
        G = RP(wP**Np - _sage_const_1 ).resultant(F, wP)
        G = Rz(G.polynomial(zP))          # G は w を含まない → z の 1 変数多項式へ
        if G == _sage_const_0 :
            return ZZ(_sage_const_0 )
        AN = Rz((zz**N - _sage_const_1 ) // (zz - _sage_const_1 ))
        part1 = AN.resultant(G)
    else:
        part1 = ZZ(_sage_const_1 )
    # part2 = ∏_{ξ≠1} F(1,ξ)
    if Np > _sage_const_1 :
        F1 = Rw(F.subs({zP: RP(_sage_const_1 )}).polynomial(wP))
        if F1 == _sage_const_0 :
            return ZZ(_sage_const_0 )
        ANp = Rw((ww**Np - _sage_const_1 ) // (ww - _sage_const_1 ))
        part2 = ANp.resultant(F1)
    else:
        part2 = ZZ(_sage_const_1 )
    return abs(ZZ(part1) * ZZ(part2))


