def random_example(rng_max_m=_sage_const_3 ):
    m = ZZ.random_element(_sage_const_1 , rng_max_m + _sage_const_1 )
    ne = ZZ.random_element(_sage_const_2 , _sage_const_6 )
    edges = []
    for _ in range(ne):
        u = ZZ.random_element(_sage_const_0 , m)
        v = ZZ.random_element(_sage_const_0 , m)
        a = ZZ.random_element(-_sage_const_2 , _sage_const_3 )
        b = ZZ.random_element(-_sage_const_2 , _sage_const_3 )
        if u == v and (a, b) == (_sage_const_0 , _sage_const_0 ):
            a = _sage_const_1 
        edges.append((u, v, (a, b)))
    return (m, edges)


