def step1():
    print("=" * _sage_const_78 )
    print("Step 1  補題 A2: charpoly(L_{X_{N,N'}}) = ∏_{ζ,ξ} charpoly(L(ζ,ξ))")
    total = _sage_const_0 
    bad = _sage_const_0 
    for (nm, m, edges) in ALL:
        for (N, Np) in [(_sage_const_1 , _sage_const_1 ), (_sage_const_2 , _sage_const_1 ), (_sage_const_1 , _sage_const_2 ), (_sage_const_2 , _sage_const_2 ), (_sage_const_2 , _sage_const_3 ), (_sage_const_3 , _sage_const_3 ), (_sage_const_4 , _sage_const_2 )]:
            if m * N * Np > _sage_const_40 :
                continue
            M = lcm(N, Np)
            K = CyclotomicField(M) if M > _sage_const_1  else QQ
            g = K.gen() if M > _sage_const_1  else K(_sage_const_1 )
            Kx = PolynomialRing(K, 'x')
            x = Kx.gen()
            Lap = int_laplacian(m * N * Np, derived_edges(m, edges, N, Np))
            lhs = Kx(Lap.charpoly())
            L = volt_laplacian(m, edges)
            rhs = Kx(_sage_const_1 )
            for i in range(N):
                for j in range(Np):
                    ze = g**(M // N * i) if M > _sage_const_1  else K(_sage_const_1 )
                    xi = g**(M // Np * j) if M > _sage_const_1  else K(_sage_const_1 )
                    Le = matrix(K, m, m, [K(c.subs(z=ze, w=xi)) for c in L.list()])
                    rhs *= (x * identity_matrix(K, m) - Le).determinant()
            total += _sage_const_1 
            if lhs != rhs:
                bad += _sage_const_1 
                print("  MISMATCH", nm, N, Np)
    print("  検査 %d 件、不一致 %d 件" % (total, bad))
    return bad


